2881: 		.abi_version = IDMA_EXPERIMENT_ABI,
2882: 		.struct_size = sizeof(caps),
2883: 		.capabilities = IDMA_EXPERIMENT_CAP_SW_REFILL | IDMA_EXPERIMENT_CAP_HW_BATCH |
2884: 				IDMA_EXPERIMENT_CAP_E3_PAIR | IDMA_EXPERIMENT_CAP_E3_DIAG |
2885: 				IDMA_EXPERIMENT_CAP_E3_QUEUE_PAIR |
2886: 				IDMA_EXPERIMENT_CAP_E3_CONTROLLED |
2887: 				IDMA_EXPERIMENT_CAP_P4M | IDMA_EXPERIMENT_CAP_RESEARCH,
2888: 		.device_id = idma->id,
2889: 		.did = idma->did,
2890: 		.max_pages = IDMA_MAX_PAGES,
2891: 		.page_bytes = PAGE_SIZE,
2892: 		.max_run_timeout_ms = IDMA_MAX_RUN_TIMEOUT_MS,
2893: 	};
2894: 
2895: 	switch (cmd) {
2896: 	case IDMA_IOC_RUN_RESEARCH:
2897: 		return idma_run_research(idma, (void __user *)arg);
2898: 	case IDMA_IOC_RUN_RESEARCH2:
2899: 		return idma_run_research2(idma, (void __user *)arg);
2900: 	case IDMA_IOC_RESEARCH2_CAPS:
2901: 		return idma_research2_caps_ioctl(idma, (void __user *)arg);
2902: 	case IDMA_IOC_RUN_E3_CONTROLLED:
2903: 		return idma_run_e3_controlled(idma, (void __user *)arg);
2904: 	case IDMA_IOC_RUN_COMPOSITION:
2905: 		return idma_run_composition(idma, (void __user *)arg);
2906: 	case IDMA_IOC_RUN_P4M:
2907: 		return idma_run_p4m(idma, (void __user *)arg);
2908: 	case IDMA_IOC_RUN_E3_QUEUE_PAIR:
2909: 		return idma_run_e3_pair(idma, (void __user *)arg, 2);
2910: 	case IDMA_IOC_RUN_E3_DIAG:
2911: 		return idma_run_e3_pair(idma, (void __user *)arg, 1);
2912: 	case IDMA_IOC_RUN_E3_PAIR:
2913: 		return idma_run_e3_pair(idma, (void __user *)arg, 0);
2914: 	case IDMA_IOC_EXPERIMENT_CAPS:
2915: 		if (riscv_iommu_hpm_supported(idma->miscdev.parent))
2916: 			caps.capabilities |= IDMA_EXPERIMENT_CAP_DID_HPM;
2917: 		return copy_to_user((void __user *)arg, &caps, sizeof(caps)) ? -EFAULT : 0;
2918: 	case IDMA_IOC_RUN_BATCH:
2919: 		return idma_run_experiment_mode(idma, (struct idma_experiment __user *)arg, true);
2920: 	case IDMA_IOC_RUN_EXPERIMENT:
2921: 		return idma_run_experiment(idma, (struct idma_experiment __user *)arg);
2922: 	default:
2923: 		return -ENOTTY;
2924: 	}
2925: }
