2513: 		     struct scatterlist *sg, unsigned int nents, int prot,
2514: 		     gfp_t gfp)
2515: {
2516: 	const struct iommu_domain_ops *ops = domain->ops;
2517: 	size_t len = 0, mapped = 0;
